  (gen_random_uuid(), 1, 'Variables', 'İşlenen sipariş tutarlarını bir toplamda biriktiriyorsun. Her yeni tutarı nasıl eklersin?', 'Toplamı önce 0 ile başlatır, her kayıtta total += amount ile güncellerim.', 'Her kayıtta total = amount yazarak önceki toplamı değiştiririm.', 'Toplamı döngünün her turunda yeniden 0 yaparım.', 'Toplamı her kayıtta iki kez artırıp tutarları sessizce çift sayarım.', 'java', 1),
  (gen_random_uuid(), 1, 'Types', 'Bir API alanı özellikle float bekliyor ve 0.75 sabitini atayacaksın. Tür uyumunu nasıl sağlarsın?', 'Sabit değeri 0.75f yazarak float türünde oluştururum.', '0.75 değerini sonek kullanmadan doğrudan float değişkene atarım.', 'Ondalık değeri int değişkende saklayıp kesilmeyi kabul ederim.', 'Değeri byte türüne daraltıp ondalık hassasiyetin korunacağını varsayarım.', 'java', 1),
  (gen_random_uuid(), 1, 'Types', 'int türündeki istek sayısını daha geniş bir long sayaçta saklayacaksın. Nasıl ilerlersin?', 'int değerini long değişkene doğrudan atar ve güvenli genişletmeden yararlanırım.', 'Değeri önce short türüne daraltıp sonra long değişkene aktarırım.', 'Sayacı float türüne çevirip long alana ondalıklı değer olarak yazarım.', 'Sayacı long yerine int alanda tutup sınırı aşan artışların doğru kalacağını varsayarım.', 'java', 1),
  (gen_random_uuid(), 1, 'Operators', 'Yeni işe mevcut sıra numarasını verip sayacı sonraki iş için artıracaksın. Hangi güncellemeyi seçersin?', 'Atamada nextId++ kullanarak mevcut değeri verir, ardından sayacı artırırım.', 'Atamada ++nextId kullanarak artırılmış değeri mevcut işe veririm.', 'nextId + 1 hesaplayıp sonucu sayaca geri yazmam.', 'Sayacı hem atama içinde hem sonraki satırda artırarak bir kimliği atlarım.', 'java', 1),
  (gen_random_uuid(), 1, 'Operators', 'Negatif olmayan görev numarasını dört iş kuyruğundan birine dağıtacaksın. Kova indisini nasıl hesaplarsın?', 'Görev numarasının 4 ile bölümünden kalanı kova indisi yaparım.', 'Görev numarasını 4''e bölüp bölüm değerini doğrudan indis yaparım.', 'Her görevi numarasından bağımsız olarak dördüncü kovaya yollarım.', 'Kalanı hesapladıktan sonra dizi uzunluğuna eşit indisi kullanırım.', 'java', 1),
  (gen_random_uuid(), 1, 'Conditionals', 'Servis etkinse aktif, değilse pasif metnini tek ifadede seçeceksin. Ternary kullanımını nasıl kurarsın?', 'active ? aktif : pasif düzeniyle koşula göre tek sonucu seçerim.', 'active ? pasif : aktif yazarak iki sonucu ters bağlarım.', 'Her iki metni de birleştirip koşuldan bağımsız döndürürüm.', 'Koşul içinde active = true ataması yapıp servis durumunu değiştiririm.', 'java', 1),
  (gen_random_uuid(), 1, 'Conditionals', 'Puan 80 ve üzerindeyse kritik, 50 ve üzerindeyse uyarı olmalı. Tek sonuç üretmek için ne yaparsın?', 'Yüksek eşikten başlayıp if ve else-if zinciriyle yalnızca bir durum seçerim.', 'Önce 50 eşiğini denetleyip 80 üzerindeki puanları da uyarı olarak bırakırım.', 'Yalnızca 50 ve 80''e eşit puanlara durum atarım.', 'Bağımsız if bloklarıyla kritik sonucunu sonradan uyarı değeriyle ezerim.', 'java', 1),
